{
  "name": "cache-demo",
  "version": "1.0.0",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "lint": "turbo run lint",
    "test": "turbo run test",
    "benchmark": "bash benchmark.sh"
  },
  "devDependencies": {
    "turbo": "latest",
    "typescript": "^5.0.0"
  }
}

export function greet(name: string): string {
  return `Hello, ${name}!`;
}

export function add(a: number, b: number): number {
  return a + b;
}

export function multiply(a: number, b: number): number {
  return a * b;
}

console.log('Core package loaded');

import { add, multiply } from '@cache-demo/core';

export function calculateSum(numbers: number[]): number {
  return numbers.reduce((acc, num) => add(acc, num), 0);
}

export function calculateProduct(numbers: number[]): number {
  return numbers.reduce((acc, num) => multiply(acc, num), 1);
}

export function formatCurrency(amount: number): string {
  return `$${amount.toFixed(2)}`;
}

console.log('Utils package loaded');

import { greet } from '@cache-demo/core';
import { calculateSum, formatCurrency } from '@cache-demo/utils';

const name = 'Turborepo';
console.log(greet(name));

const numbers = [10, 20, 30, 40, 50];
const sum = calculateSum(numbers);
console.log(`Sum of ${numbers.join(', ')} = ${sum}`);
console.log(`Formatted: ${formatCurrency(sum)}`);

console.log('✅ App built successfully!');

